// ============================================
// HOLEY MOLEY FEEDBACK REPORT - CSV PROCESSOR
// WITH DYNAMIC FISCAL CALENDAR ENGINE
// ============================================

// ---- FISCAL CALENDAR ENGINE ----
const FY_ANCHOR = new Date('2024-07-01T00:00:00');
const FY_DAYS = 364;
const MS_PER_DAY = 86400000;

// Helper: set date to end of day for inclusive range checks
function endOfDay(d) {
  const eod = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999);
  return eod;
}
// Helper: set date to start of day
function startOfDay(d) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0);
}

function getFiscalInfo(dateObj) {
  // Normalize to midnight
  const d = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
  const daysSinceAnchor = Math.floor((d - FY_ANCHOR) / MS_PER_DAY);

  const fyIndex = Math.floor(daysSinceAnchor / FY_DAYS);
  const dayInFY = daysSinceAnchor % FY_DAYS;

  const fyStartYear = 2024 + fyIndex;
  const fyLabel = 'FY' + String(fyStartYear % 100).padStart(2, '0') + '-' + String((fyStartYear + 1) % 100).padStart(2, '0');

  const weekNum = Math.floor(dayInFY / 7) + 1;
  const periodNum = Math.floor((weekNum - 1) / 4) + 1;
  const weekInPeriod = ((weekNum - 1) % 4) + 1;

  const fyStart = new Date(FY_ANCHOR.getTime() + fyIndex * FY_DAYS * MS_PER_DAY);
  const fyEnd = new Date(fyStart.getTime() + (FY_DAYS - 1) * MS_PER_DAY);

  const weekStart = new Date(fyStart.getTime() + (weekNum - 1) * 7 * MS_PER_DAY);
  const weekEnd = new Date(weekStart.getTime() + 6 * MS_PER_DAY);

  const periodStartWk = (periodNum - 1) * 4 + 1;
  const periodStart = new Date(fyStart.getTime() + (periodStartWk - 1) * 7 * MS_PER_DAY);
  const periodEnd = new Date(periodStart.getTime() + 27 * MS_PER_DAY);

  return {
    fyLabel, fyStartYear, fyStart, fyEnd,
    periodNum, periodLabel: 'P' + String(periodNum).padStart(2, '0'),
    periodStart, periodEnd,
    weekNum, weekLabel: 'WK' + weekNum,
    weekInPeriod,
    weekStart, weekEnd
  };
}



function parseCSV(csvText) {
  // Full CSV parser that handles multi-line quoted fields (reviews with line breaks)
  const rows = [];
  const fields = [];
  let current = '';
  let inQuotes = false;
  let i = 0;

  while (i < csvText.length) {
    const char = csvText[i];

    if (inQuotes) {
      if (char === '"') {
        if (i + 1 < csvText.length && csvText[i + 1] === '"') {
          // Escaped quote
          current += '"';
          i += 2;
          continue;
        } else {
          // End of quoted field
          inQuotes = false;
          i++;
          continue;
        }
      } else {
        current += char;
        i++;
        continue;
      }
    }

    // Not in quotes
    if (char === '"') {
      inQuotes = true;
      i++;
    } else if (char === ',') {
      fields.push(current.trim());
      current = '';
      i++;
    } else if (char === '\n' || char === '\r') {
      // End of row (skip \r\n)
      if (char === '\r' && i + 1 < csvText.length && csvText[i + 1] === '\n') {
        i++;
      }
      fields.push(current.trim());
      current = '';
      if (fields.some(f => f !== '')) {
        rows.push([...fields]);
      }
      fields.length = 0;
      i++;
    } else {
      current += char;
      i++;
    }
  }

  // Last row
  if (current || fields.length > 0) {
    fields.push(current.trim());
    if (fields.some(f => f !== '')) {
      rows.push([...fields]);
    }
  }

  if (rows.length < 2) return [];

  const header = rows[0];
  const result = [];
  for (let r = 1; r < rows.length; r++) {
    const row = {};
    header.forEach((col, idx) => {
      row[col] = rows[r][idx] !== undefined ? rows[r][idx] : '';
    });
    // Only include rows that have a Review ID (skip malformed partial rows)
    if (row['Review ID'] && row['Review ID'].length > 5) {
      result.push(row);
    }
  }
  return result;
}

function parseDate(dateStr) {
  if (!dateStr) return null;
  // Parse dates like "2026-03-29 06:42:21 PM" - extract just the date part
  // to avoid timezone shifts that could move a review to the wrong day
  const match = dateStr.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (match) {
    // Create date at noon local time to avoid any timezone day-shift
    return new Date(parseInt(match[1]), parseInt(match[2]) - 1, parseInt(match[3]), 12, 0, 0);
  }
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? null : d;
}

function formatDate(d) {
  return d.toISOString().split('T')[0];
}

function getOrdinalSuffix(day) {
  if (day > 3 && day < 21) return 'th';
  switch (day % 10) {
    case 1: return 'st';
    case 2: return 'nd';
    case 3: return 'rd';
    default: return 'th';
  }
}

function formatDateDisplay(d) {
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const day = d.getDate();
  return months[d.getMonth()] + ' ' + day + getOrdinalSuffix(day);
}

function getDayName(d) {
  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()];
}

function computeMetrics(allReviews, weekStart, weekEnd, periodStart, periodEnd, fyStart, fyEnd) {
  const wsDate = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate());
  const weDate = new Date(weekEnd.getFullYear(), weekEnd.getMonth(), weekEnd.getDate());
  weDate.setHours(23, 59, 59, 999);

  const psDate = new Date(periodStart.getFullYear(), periodStart.getMonth(), periodStart.getDate());
  const peDate = new Date(periodEnd.getFullYear(), periodEnd.getMonth(), periodEnd.getDate());
  peDate.setHours(23, 59, 59, 999);

  const fysDate = new Date(fyStart.getFullYear(), fyStart.getMonth(), fyStart.getDate());
  const fyeDate = new Date(fyEnd.getFullYear(), fyEnd.getMonth(), fyEnd.getDate());
  fyeDate.setHours(23, 59, 59, 999);

  const weekReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= wsDate && d <= weDate;
  });

  const activeWeek = weekReviews.filter(r => !r['Deleted'] || r['Deleted'].trim() === '');
  const deletedWeek = weekReviews.filter(r => r['Deleted'] && r['Deleted'].trim() !== '');

  const weeklyAvg = activeWeek.length > 0 
    ? Math.round((activeWeek.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / activeWeek.length) * 100) / 100 
    : 0;

  const ptdReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= psDate && d <= peDate && true /* deleted already stripped */;
  });
  const ptdAvg = ptdReviews.length > 0
    ? Math.round((ptdReviews.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / ptdReviews.length) * 100) / 100
    : 0;

  const ytdReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= fysDate && d <= fyeDate && true /* deleted already stripped */;
  });
  const ytdAvg = ytdReviews.length > 0
    ? Math.round((ytdReviews.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / ytdReviews.length) * 100) / 100
    : 0;

  const ratingDist = {};
  for (let i = 5; i >= 1; i--) {
    const count = activeWeek.filter(r => Math.round(parseFloat(r['Rating'])) === i).length;
    const pct = activeWeek.length > 0 ? Math.round((count / activeWeek.length) * 100) : 0;
    ratingDist[i] = { count, pct };
  }

  const sources = {};
  activeWeek.forEach(r => {
    const src = r['Source'] || 'Unknown';
    sources[src] = (sources[src] || 0) + 1;
  });

  const ptdDeleted = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= psDate && d <= peDate && r['Deleted'] && r['Deleted'].trim() !== '';
  }).length;

  const ytdDeleted = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= fysDate && d <= fyeDate && r['Deleted'] && r['Deleted'].trim() !== '';
  }).length;

  // ---- STAFF NAME DROP EXTRACTION (canonical roster + alias normalization) ----
  // Each canonical name in the report = $5 staff payout, so this must be deterministic
  // and conservative. Source roster: ~/Desktop/hm staff names.rtf (20 staff).
  const nameDropsThisWeek = {};
  const nameDropsThisPeriod = {};
  for (const r of activeWeek) {
    const drops = extractStaffDrops(r['Review'] || '');
    for (const name of drops) nameDropsThisWeek[name] = (nameDropsThisWeek[name] || 0) + 1;
  }
  for (const r of ptdReviews) {
    const drops = extractStaffDrops(r['Review'] || '');
    for (const name of drops) nameDropsThisPeriod[name] = (nameDropsThisPeriod[name] || 0) + 1;
  }
  // Final report section: only staff with drops THIS WEEK, sorted desc by week_delta
  const nameDropsSection = Object.entries(nameDropsThisWeek)
    .map(([name, week]) => ({
      name,
      period_total: nameDropsThisPeriod[name] || 0,
      week_delta: week,
    }))
    .sort((a, b) => b.week_delta - a.week_delta || a.name.localeCompare(b.name));

  const dailyBreakdown = {};
  activeWeek.forEach(r => {
    const d = parseDate(r['Published']);
    if (!d) return;
    const dayKey = formatDate(d);
    if (!dailyBreakdown[dayKey]) {
      dailyBreakdown[dayKey] = { date: d, positive: 0, neutral: 0, negative: 0, reviews: [] };
    }
    const rating = parseFloat(r['Rating']);
    if (rating >= 4) dailyBreakdown[dayKey].positive++;
    else if (rating === 3) dailyBreakdown[dayKey].neutral++;
    else dailyBreakdown[dayKey].negative++;
    dailyBreakdown[dayKey].reviews.push(r);
  });

  return {
    totalReviews: activeWeek.length,
    weeklyAvg,
    ptdAvg,
    ptdCount: ptdReviews.length,
    ytdAvg,
    ytdCount: ytdReviews.length,
    deletedThisWeek: deletedWeek.length,
    deletedPTD: ptdDeleted,
    deletedYTD: ytdDeleted,
    ratingDist,
    sources,
    nameDropsSection,
    nameDropsThisWeek,
    nameDropsThisPeriod,
    dailyBreakdown,
    activeReviews: activeWeek,
    deletedReviews: deletedWeek
  };
}

// ---- CANONICAL STAFF ROSTER + ALIAS MAP ----
// Aliases (lowercase) → canonical display name. Source: ~/Desktop/hm staff names.rtf.
const ALIAS_MAP = {
  'alena': 'Alena', 'lena': 'Alena',
  'andre': 'Andre',
  'ashley': 'Ashley',
  'austin': 'Austin',
  'boon': 'Boon',
  'brooklynn': 'Brooklynn',
  'danielle': 'Danielle',
  'emily': 'Emily',
  'gabriel': 'Gabriel', 'gabe': 'Gabriel',
  'jarvis': 'Jarvis',
  'jay': 'Jay',
  'jess': 'Jess', 'jessica': 'Jess',
  'kara': 'Kara',
  'kayla': 'Kayla',
  'kurtis': 'Kurtis',
  'marshal': 'Marshal',
  'mel': 'Mel', 'melly': 'Mel', 'melanie': 'Mel',
  'michael': 'Michael',
  'roman': 'Roman',
  'sofia': 'Sofia', 'sophia': 'Sofia',
};
const STAFF_TOKENS = Object.keys(ALIAS_MAP).sort((a, b) => b.length - a.length);
const STAFF_REGEX = new RegExp('\\b(' + STAFF_TOKENS.join('|') + ')\\b', 'gi');
// Canonical names (deduped values from ALIAS_MAP) for fuzzy matching of misspellings
const CANONICAL_NAMES = Array.from(new Set(Object.values(ALIAS_MAP)));
// "Austin" the staff name vs "Austin" the city — only count when a name-context cue is present
const AUSTIN_NAME_CTX = /(?:shout(?:\s|-)?out\s+to|thanks?\s+(?:to\s+)?|named?\s+|ask(?:ed|ing)?\s+for\s+|helped\s+by\s+|served\s+by\s+|bartender|server|host(?:ess)?|manager|dealer|guide)\s*[:,-]?\s*Austin\b|\bAustin\s+(?:was|is|did|made|helped|served|hosted|guided|rocked|killed)/i;

// Levenshtein edit distance — used to forgive misspellings of staff names
// (e.g., "Romon was great" → Roman, "Sophia made the drinks" → Sofia).
function levenshtein(a, b) {
  if (a === b) return 0;
  const al = a.length, bl = b.length;
  if (al === 0) return bl;
  if (bl === 0) return al;
  const v0 = new Array(bl + 1);
  const v1 = new Array(bl + 1);
  for (let i = 0; i <= bl; i++) v0[i] = i;
  for (let i = 0; i < al; i++) {
    v1[0] = i + 1;
    for (let j = 0; j < bl; j++) {
      const cost = a[i] === b[j] ? 0 : 1;
      v1[j + 1] = Math.min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost);
    }
    for (let j = 0; j <= bl; j++) v0[j] = v1[j];
  }
  return v0[bl];
}

// Capture words used in clear name contexts so we can fuzzy-match misspellings safely.
// We only fuzzy-match within these patterns to avoid matching random capitalized words.
const NAME_CTX_REGEXES = [
  // "{Name} was great", "{Name} helped us", "{Name} hosted", etc.
  /\b([A-Z][a-z]{3,})\s+(?:was|is|were|seemed|made|made\s+us|made\s+sure|helped|served|hosted|guided|crushed|nailed|killed|treated|recommended|suggested|brought|took|took\s+care|kept|rocked)\b/g,
  // "shoutout to {Name}", "thanks to {Name}", "credit to {Name}"
  /(?:shout(?:\s|-)?out\s+to|thanks?\s+to|big\s+thanks?\s+to|credit\s+to|kudos\s+to)\s+([A-Z][a-z]{3,})\b/gi,
  // "ask for {Name}" / "asked for {Name}"
  /\bask(?:ed|ing)?\s+for\s+([A-Z][a-z]{3,})\b/gi,
  // "our bartender {Name}", "named {Name}", "by {Name}"
  /\b(?:our|the|with|by|named?)\s+(?:bartender|server|host|hostess|manager|dealer|guide|mc|staff)\s+([A-Z][a-z]{3,})\b/gi,
  // "{Name} the bartender", "{Name} our server"
  /\b([A-Z][a-z]{3,})\s+(?:the\s+|our\s+)?(?:bartender|server|host|hostess|manager|dealer|guide)\b/g,
];

function fuzzyMatchCanonical(word) {
  const wl = word.toLowerCase();
  if (ALIAS_MAP[wl]) return ALIAS_MAP[wl];
  // Skip very short words — too easy to false-match (Jay/Mel)
  if (wl.length < 4) return null;
  let best = null, bestDist = Infinity;
  for (const canonical of CANONICAL_NAMES) {
    const cl = canonical.toLowerCase();
    if (Math.abs(cl.length - wl.length) > 2) continue;
    const d = levenshtein(wl, cl);
    if (d < bestDist) { bestDist = d; best = canonical; }
  }
  // Conservative threshold: 1 edit for short names (4-6 chars), 2 for longer (7+)
  const threshold = wl.length >= 7 ? 2 : 1;
  return bestDist <= threshold ? best : null;
}

function extractStaffDrops(text) {
  if (!text) return new Set();
  const found = new Set();
  // Pass 1: exact alias regex (handles correctly-spelled names anywhere in text)
  for (const m of text.matchAll(STAFF_REGEX)) {
    const canonical = ALIAS_MAP[m[1].toLowerCase()];
    if (!canonical) continue;
    if (canonical === 'Austin' && !AUSTIN_NAME_CTX.test(text)) continue;
    found.add(canonical);
  }
  // Pass 2: fuzzy match misspelled names, but ONLY when they appear in a name context.
  // Restricting to context patterns keeps false-positives down (random capitalized words don't fuzzy-match).
  for (const re of NAME_CTX_REGEXES) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(text)) !== null) {
      const canonical = fuzzyMatchCanonical(m[1]);
      if (!canonical) continue;
      if (canonical === 'Austin' && !AUSTIN_NAME_CTX.test(text)) continue;
      found.add(canonical);
    }
  }
  return found;
}

function formatAuthorName(author) {
  if (!author) return 'Anonymous';
  const parts = author.trim().split(/\s+/);
  if (parts.length === 0) return 'Anonymous';
  if (parts.length === 1) return parts[0];
  return parts[0] + ' ' + parts[1][0] + '.';
}

// Read CSV data — track NEW csv vs MASTER csv separately
const items = $input.all();
let newCsvText = '';   // From the uploaded CSV
let reportMemoryData = [];  // From report_memory.json (item 0 = Download CSV)
let masterCsvText = ''; // From master_reviews.csv (item 1 = Download Master)

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      try {
        const buffer = await helpers.getBinaryDataBuffer(i, key);
        const text = buffer.toString('utf-8');
        if (text && text.includes(',') && (text.toLowerCase().includes('review') || text.toLowerCase().includes('rating') || text.toLowerCase().includes('published'))) {
          if (i === 0 && !newCsvText) {
            newCsvText = text;  // First item = new CSV from trigger
          } else if (!masterCsvText) {
            masterCsvText = text; // Second item = master
          }
        } else if ((text.trim().startsWith('[') || text.trim().startsWith('{')) && (text.includes('generatedAt') || text.includes('periodNameDrops'))) {
          // Report memory JSON — legacy array OR new {summaries, periodNameDrops} object
          try { reportMemoryData = JSON.parse(text); } catch(e) {}
        }
      } catch(e) {
        const binaryObj = item.binary[key];
        if (binaryObj.data && typeof binaryObj.data === 'string' && binaryObj.data.length > 100) {
          try {
            const text = Buffer.from(binaryObj.data, 'base64').toString('utf-8');
            if (text && text.includes(',')) {
              if (i === 0 && !newCsvText) newCsvText = text;
              else if (!masterCsvText) masterCsvText = text;
            }
          } catch(e2) {}
        }
      }
    }
  }
}

// Normalize report memory: legacy = array, new = {summaries, periodNameDrops}
let storedPeriodNameDrops = {};
if (reportMemoryData && !Array.isArray(reportMemoryData) && typeof reportMemoryData === 'object') {
  storedPeriodNameDrops = reportMemoryData.periodNameDrops || {};
  reportMemoryData = reportMemoryData.summaries || [];
}

if (!newCsvText) {
  throw new Error('No new CSV data found in uploaded file');
}

// Parse the NEW CSV to determine report week
const newReviewsRaw = parseCSV(newCsvText);
const newReviews = newReviewsRaw.filter(r => !r['Deleted'] || r['Deleted'].trim() === '');
if (newReviews.length === 0) {
  throw new Error('No reviews found in uploaded CSV');
}

// Find the date range of the NEW reviews (this determines the report week)
const newDates = newReviews.map(r => parseDate(r['Published'])).filter(d => d !== null);
newDates.sort((a, b) => a - b);
const newLatestDate = newDates[newDates.length - 1];
const newEarliestDate = newDates[0];

// Parse master CSV for comparison data
const masterReviews = masterCsvText ? parseCSV(masterCsvText) : [];

// Merge ALL reviews (new + master), deduplicate by Review ID
const reviewMap = new Map();
const allParsed = [...masterReviews, ...newReviews];
for (const r of allParsed) {
  const id = r['Review ID'];
  if (!id) continue;
  const existing = reviewMap.get(id);
  if (!existing) {
    reviewMap.set(id, r);
  } else {
    const existingDate = parseDate(existing['Updated'] || existing['Published']);
    const newDate = parseDate(r['Updated'] || r['Published']);
    if (newDate && existingDate && newDate > existingDate) {
      reviewMap.set(id, r);
    }
  }
}
const allReviewsRaw = Array.from(reviewMap.values());
// Strip deleted reviews entirely — they don't exist for any calculation
const allReviews = allReviewsRaw.filter(r => !r['Deleted'] || r['Deleted'].trim() === '');

// Build merged CSV for saving as master
const firstCsv = newCsvText || masterCsvText;
const firstNewline = firstCsv.indexOf('\n');
const headerLine = firstCsv.substring(0, firstNewline > 0 ? firstNewline : 200).replace(/\r/g, '');
const headers = headerLine || Object.keys(allReviews[0] || {}).join(',');
const csvRows = [headers];
for (const r of allReviews) {
  const row = Object.values(r).map(v => {
    const s = String(v || '');
    return s.includes(',') || s.includes('\n') || s.includes('"') ? '"' + s.replace(/"/g, '""') + '"' : s;
  });
  csvRows.push(row.join(','));
}
const mergedCsvText = csvRows.join('\n');

if (allReviews.length === 0) {
  throw new Error('No reviews found after parsing ' + csvTexts.length + ' CSV files');
}
// ============================================

// Report week determined by NEW CSV's dates (newLatestDate set above)
const fiscalInfo = getFiscalInfo(newLatestDate);
const { fyLabel, fyStart, fyEnd, periodNum, periodLabel, periodStart, periodEnd, weekNum, weekStart, weekEnd } = fiscalInfo;

const metrics = computeMetrics(allReviews, weekStart, weekEnd, periodStart, periodEnd, fyStart, fyEnd);

// ---- ACCUMULATED PERIOD NAME DROPS (persisted in report_memory.json) ----
// Sum prior weeks of current period from stored counter, add this week's drops.
// New period implicitly resets (no entries yet). Re-runs of same week are idempotent.
const periodKey = fyLabel + '-' + periodLabel;
const weekKey = 'WK' + weekNum;
const periodHistory = (storedPeriodNameDrops && storedPeriodNameDrops[periodKey]) || {};
const accumulatedPeriodDrops = {};
for (const [wk, counts] of Object.entries(periodHistory)) {
  if (wk === weekKey) continue;
  for (const [name, c] of Object.entries(counts || {})) {
    accumulatedPeriodDrops[name] = (accumulatedPeriodDrops[name] || 0) + c;
  }
}
for (const [name, c] of Object.entries(metrics.nameDropsThisWeek || {})) {
  accumulatedPeriodDrops[name] = (accumulatedPeriodDrops[name] || 0) + c;
}
metrics.nameDropsSection = (metrics.nameDropsSection || []).map(d => ({
  ...d,
  period_total: accumulatedPeriodDrops[d.name] || d.week_delta
}));
metrics.nameDropsThisPeriod = accumulatedPeriodDrops;
const periodNameDropsUpdate = {
  [periodKey]: { ...periodHistory, [weekKey]: metrics.nameDropsThisWeek || {} }
};
// Stale reports: weeks already processed AFTER current week have outdated period_total totals
const staleReports = Object.keys(periodHistory)
  .map(wk => parseInt(String(wk).replace(/^WK/, ''), 10))
  .filter(n => Number.isFinite(n) && n > weekNum)
  .sort((a, b) => a - b)
  .map(n => 'WK' + n);

// All-time average from ALL non-deleted reviews in CSV
const allTimeActive = allReviews.filter(r => !r['Deleted'] || r['Deleted'].trim() === '');
metrics.allTimeAvg = allTimeActive.length > 0
  ? Math.round((allTimeActive.reduce((s, r) => s + parseFloat(r['Rating']), 0) / allTimeActive.length) * 100) / 100
  : 0;
metrics.allTimeCount = allTimeActive.length;

// YTD average as of LAST WEEK (excludes this week's reviews)
const ytdLwReviews = allReviews.filter(r => {
  const d = parseDate(r['Published']);
  return d && d >= startOfDay(fyStart) && d < startOfDay(weekStart)
    && true /* deleted already stripped */;
});
metrics.ytdLastWeekAvg = ytdLwReviews.length > 0
  ? Math.round((ytdLwReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / ytdLwReviews.length) * 100) / 100
  : null;

// PTD average as of LAST WEEK (excludes this week's reviews)
const ptdLwReviews = allReviews.filter(r => {
  const d = parseDate(r['Published']);
  return d && d >= startOfDay(periodStart)
    && d < startOfDay(weekStart)
    && true /* deleted already stripped */;
});
metrics.ptdLastWeekAvg = ptdLwReviews.length > 0
  ? Math.round((ptdLwReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / ptdLwReviews.length) * 100) / 100
  : null;

const wsDisplay = formatDateDisplay(weekStart);
const weDisplay = formatDateDisplay(weekEnd);

// Compute PRIOR WEEK metrics directly from CSV
const priorWeekStart = startOfDay(new Date(weekStart.getTime() - 7 * MS_PER_DAY));
const priorWeekEnd = endOfDay(new Date(weekEnd.getTime() - 7 * MS_PER_DAY));
const priorWeekReviews = allReviews.filter(r => {
  const d = parseDate(r['Published']);
  return d && d >= priorWeekStart && d <= priorWeekEnd && true /* deleted already stripped */;
});
let priorWeekMetrics = null;
if (priorWeekReviews.length > 0) {
  const pwAvg = Math.round((priorWeekReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / priorWeekReviews.length) * 100) / 100;
  // Build rating distribution for prior week
  const pwRatingDist = {};
  for (let s = 1; s <= 5; s++) {
    pwRatingDist[s] = { count: priorWeekReviews.filter(r => Math.round(parseFloat(r['Rating'])) === s).length };
  }
  priorWeekMetrics = { totalReviews: priorWeekReviews.length, weeklyAvg: pwAvg, ratingDist: pwRatingDist };
}

// Compute PRIOR PERIOD metrics directly from CSV
const priorPeriodNum = periodNum > 1 ? periodNum - 1 : 13;
const priorPeriodFyLabel = periodNum > 1 ? fyLabel : 'FY' + String((fiscalInfo.fyStartYear - 1) % 100).padStart(2, '0') + '-' + String(fiscalInfo.fyStartYear % 100).padStart(2, '0');
const priorPeriodStartWk = (priorPeriodNum - 1) * 4 + 1;
const priorPeriodFyStart = periodNum > 1 ? fyStart : new Date(fyStart.getTime() - FY_DAYS * MS_PER_DAY);
const ppStart = new Date(priorPeriodFyStart.getTime() + (priorPeriodStartWk - 1) * 7 * MS_PER_DAY);
const ppEnd = new Date(ppStart.getTime() + 27 * MS_PER_DAY);
const ppStartDay = startOfDay(ppStart);
const ppEndDay = endOfDay(ppEnd);
const priorPeriodReviews = allReviews.filter(r => {
  const d = parseDate(r['Published']);
  return d && d >= ppStartDay && d <= ppEndDay && true /* deleted already stripped */;
});
let priorPeriodMetrics = null;
let priorPeriodNameDrops = {};
let priorPeriodThemes = {};
if (priorPeriodReviews.length > 0) {
  const ppAvg = Math.round((priorPeriodReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / priorPeriodReviews.length) * 100) / 100;
  // Name drops in prior period (for delta comparison)
  for (const r of priorPeriodReviews) {
    const drops = extractStaffDrops(r['Review'] || '');
    for (const name of drops) priorPeriodNameDrops[name] = (priorPeriodNameDrops[name] || 0) + 1;
  }
  // Theme keyword counts in prior period (for actionable trend deltas)
  const themeKeywords = ['staff', 'bartender', 'service', 'food', 'drinks', 'golf', 'darts', 'karaoke', 'atmosphere', 'vibe', 'fun', 'price', 'expensive', 'crowded', 'wait', 'music', 'birthday', 'group', 'rude', 'slow'];
  priorPeriodReviews.forEach(r => {
    const text = (r['Review'] || '').toLowerCase();
    themeKeywords.forEach(kw => {
      if (text.includes(kw)) priorPeriodThemes[kw] = (priorPeriodThemes[kw] || 0) + 1;
    });
  });
  priorPeriodMetrics = { totalReviews: priorPeriodReviews.length, weeklyAvg: ppAvg, periodLabel: 'P' + String(priorPeriodNum).padStart(2, '0') };
}

// PTD history (other weeks in current period before this week)
let ptdHistoryMetrics = null;
const otherPtdReviews = allReviews.filter(r => {
  const d = parseDate(r['Published']);
  return d && d >= startOfDay(periodStart) && d < startOfDay(weekStart) && true /* deleted already stripped */;
});
if (otherPtdReviews.length > 0) {
  const ptdAvg = Math.round((otherPtdReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / otherPtdReviews.length) * 100) / 100;
  ptdHistoryMetrics = { totalReviews: otherPtdReviews.length, weeklyAvg: ptdAvg };
}


// ═══════════════════════════════════════════════
// HISTORICAL WEEKLY ANALYSIS (last 8 weeks from CSV)
// Gives Claude context for trends and actionable insights
// ═══════════════════════════════════════════════
const weeklyHistory = [];
for (let w = 0; w < 8; w++) {
  const wkStart = new Date(weekStart.getTime() - w * 7 * MS_PER_DAY);
  const wkEnd = new Date(wkStart.getTime() + 6 * MS_PER_DAY);
  wkEnd.setHours(23, 59, 59, 999);
  const wkReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= wkStart && d <= wkEnd && true /* deleted already stripped */;
  });
  if (wkReviews.length > 0) {
    const avg = Math.round((wkReviews.reduce((s, r) => s + parseFloat(r['Rating']), 0) / wkReviews.length) * 100) / 100;
    const stars5 = wkReviews.filter(r => Math.round(parseFloat(r['Rating'])) === 5).length;
    const detract = wkReviews.filter(r => parseFloat(r['Rating']) <= 2).length;
    // Top themes from this week
    const themes = {};
    wkReviews.forEach(r => {
      const text = (r['Review'] || '').toLowerCase();
      ['staff', 'bartender', 'service', 'food', 'drinks', 'golf', 'darts', 'karaoke', 'atmosphere', 'vibe', 'fun', 'price', 'expensive', 'crowded', 'wait', 'music'].forEach(kw => {
        if (text.includes(kw)) themes[kw] = (themes[kw] || 0) + 1;
      });
    });
    const topThemes = Object.entries(themes).sort((a,b) => b[1]-a[1]).slice(0, 5).map(([k,v]) => k + '(' + v + ')').join(', ');
    weeklyHistory.push({
      weekLabel: 'WK' + getFiscalInfo(wkStart).weekNum,
      start: formatDate(wkStart),
      end: formatDate(wkEnd),
      count: wkReviews.length,
      avg,
      stars5pct: Math.round(stars5 / wkReviews.length * 100),
      detractors: detract,
      themes: topThemes || 'none'
    });
  }
}

// Compute OVERALL weekly average across all weeks in the CSV
const allWeeklyAvgs = [];
let scanDate = new Date(allReviews.reduce((earliest, r) => {
  const d = parseDate(r['Published']);
  return d && d < earliest ? d : earliest;
}, new Date()).getTime());
// Round to Monday
scanDate.setDate(scanDate.getDate() - scanDate.getDay() + 1);
const endScan = new Date(weekEnd.getTime());
while (scanDate < endScan) {
  const scanEnd = new Date(scanDate.getTime() + 6 * MS_PER_DAY);
  scanEnd.setHours(23, 59, 59, 999);
  const wkR = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= scanDate && d <= scanEnd && true /* deleted already stripped */;
  });
  if (wkR.length > 0) {
    allWeeklyAvgs.push({
      count: wkR.length,
      avg: wkR.reduce((s, r) => s + parseFloat(r['Rating']), 0) / wkR.length
    });
  }
  scanDate = new Date(scanDate.getTime() + 7 * MS_PER_DAY);
}
const overallWeeklyAvgRating = allWeeklyAvgs.length > 0
  ? Math.round((allWeeklyAvgs.reduce((s, w) => s + w.avg, 0) / allWeeklyAvgs.length) * 100) / 100
  : 0;
const overallWeeklyAvgCount = allWeeklyAvgs.length > 0
  ? Math.round(allWeeklyAvgs.reduce((s, w) => s + w.count, 0) / allWeeklyAvgs.length)
  : 0;
metrics.overallWeeklyAvgRating = overallWeeklyAvgRating;
metrics.overallWeeklyAvgCount = overallWeeklyAvgCount;


// ── PRIOR WEEK full review details (for 2-week analysis) ──
let priorWeekReviewList = '';
if (priorWeekReviews.length > 0) {
  priorWeekReviewList = '\nPRIOR WEEK REVIEWS (' + formatDate(priorWeekStart) + ' to ' + formatDate(priorWeekEnd) + ', ' + priorWeekReviews.length + ' reviews, avg ' + priorWeekMetrics.weeklyAvg + '★):\n';
  priorWeekReviews.forEach(r => {
    const author = formatAuthorName(r['Author']);
    const rating = parseFloat(r['Rating']);
    const source = r['Source'] || 'Unknown';
    const text = r['Review'] || '(no comment)';
    priorWeekReviewList += '- ' + author + ' (' + rating + '★ ' + source + '): ' + text.substring(0, 200) + '\n';
  });
}

const promoters = metrics.activeReviews.filter(r => parseFloat(r['Rating']) >= 4);
const neutrals = metrics.activeReviews.filter(r => Math.round(parseFloat(r['Rating'])) === 3);
const detractors = metrics.activeReviews.filter(r => parseFloat(r['Rating']) <= 2);

function buildReviewList(reviews) {
  return reviews.map(r => {
    const author = formatAuthorName(r['Author']);
    const rating = parseFloat(r['Rating']);
    const source = r['Source'] || 'Unknown';
    const date = r['Published'] ? r['Published'].split(' ')[0] : '';
    const text = r['Review'] || '(no comment)';
    return '- ' + author + ' (' + rating + '★ ' + source + ', ' + date + '): ' + text;
  }).join('\n');
}

let comparisonStr = '';
if (priorWeekMetrics) {
  const changeReviews = metrics.totalReviews - priorWeekMetrics.totalReviews;
  const arrow = changeReviews >= 0 ? '↑' : '↓';
  const changeRating = metrics.weeklyAvg - priorWeekMetrics.weeklyAvg;
  const ratingArrow = changeRating >= 0 ? '↑' : '↓';
  comparisonStr += '\n- Prior Week: ' + priorWeekMetrics.totalReviews + ' reviews at ' + priorWeekMetrics.weeklyAvg + '★ (' + arrow + Math.abs(changeReviews) + ' reviews, rating: ' + ratingArrow + Math.abs(changeRating).toFixed(2) + ')';
}
comparisonStr += '\n- Overall Weekly Average (all ' + allWeeklyAvgs.length + ' weeks): ' + overallWeeklyAvgRating + '★, ~' + overallWeeklyAvgCount + ' reviews/week';
comparisonStr += '\n- This week vs overall: ' + (metrics.weeklyAvg >= overallWeeklyAvgRating ? '↑' : '↓') + ' ' + Math.abs(metrics.weeklyAvg - overallWeeklyAvgRating).toFixed(2) + ' from the weekly average';
if (priorPeriodMetrics) {
  comparisonStr += '\n- Prior Period (' + priorPeriodMetrics.periodLabel + '): ' + priorPeriodMetrics.totalReviews + ' reviews at ' + priorPeriodMetrics.weeklyAvg + '★';
  comparisonStr += '\n- ' + periodLabel + ' to date vs ' + priorPeriodMetrics.periodLabel + ': ' + (metrics.ptdAvg >= priorPeriodMetrics.weeklyAvg ? '↑' : '↓') + ' ' + Math.abs(metrics.ptdAvg - priorPeriodMetrics.weeklyAvg).toFixed(2);
}
if (metrics.ytdLastWeekAvg !== null) {
  comparisonStr += '\n- YTD last week: ' + metrics.ytdLastWeekAvg + '★ → this week: ' + metrics.ytdAvg + '★ (' + (metrics.ytdAvg >= metrics.ytdLastWeekAvg ? '↑' : '↓') + ' ' + Math.abs(metrics.ytdAvg - metrics.ytdLastWeekAvg).toFixed(3) + ')';
}

// 8-week trend summary for Claude
let trendSummary = '\n\nRECENT 8-WEEK TREND (most recent first):\n';
weeklyHistory.forEach(w => {
  trendSummary += w.weekLabel + ' (' + w.start + '): ' + w.count + ' reviews, ' + w.avg + '★, 5★ rate: ' + w.stars5pct + '%, detractors: ' + w.detractors + ', themes: ' + w.themes + '\n';
});
comparisonStr += trendSummary;


// Build dynamic memory context from past reports
let historyContext = '';
if (reportMemoryData.length > 0) {
  historyContext = 'PAST REPORT SUMMARIES (' + reportMemoryData.length + ' reports in memory):\n';
  reportMemoryData.slice(-12).forEach(r => {
    historyContext += '- ' + r.fy + ' ' + r.period + ' WK' + r.week + ' (' + r.dates + '): ' + r.reviews + ' reviews, avg ' + r.avg + '\n';
    if (r.executive) historyContext += '  Summary: ' + r.executive + '\n';
    if (r.positiveTrends && r.positiveTrends.length) historyContext += '  Positive: ' + r.positiveTrends.join('; ') + '\n';
    if (r.negativeTrends && r.negativeTrends.length) historyContext += '  Negative: ' + r.negativeTrends.join('; ') + '\n';
  });
  historyContext += '\nRECURRING PATTERNS FROM 76 PAST REPORTS:\n';
  historyContext += 'Top positives: staff (41 weeks), fun (30), atmosphere (24), events (22), groups (21), golf (20), vibe (18), food (16)\n';
  historyContext += 'Top negatives: value/pricing (14), consistency (13), booking (12), wait times (12), refund (6)\n';
  historyContext += '\nUSE THIS TO: reference evolving patterns, note improvements, make actionable recommendations that BUILD on past insights.\n';
} else {
  historyContext = 'RECURRING PATTERNS FROM 76 PAST REPORTS:\nTop positives: staff (41 weeks), fun (30), atmosphere (24), events (22), groups (21), golf (20), vibe (18), food (16)\nTop negatives: value/pricing (14), consistency (13), booking (12), wait times (12), refund (6)\nUse these patterns for context in your analysis.\n';
}

const claudePrompt = 'You are generating a weekly customer feedback report for Holey Moley Austin (a mini golf bar venue). The biweekly guest experience meeting covers the LAST 2 WEEKS, so always compare and contrast this week vs the prior week in your analysis. You have access to historical context from 76 past reports — use it to identify trends, patterns, and make actionable recommendations that BUILD on past insights.\\n\\n' +
'REPORT PERIOD: Week ' + weekNum + ' (' + periodLabel + ') — ' + wsDisplay + ' – ' + weDisplay + '\\n' +
'FISCAL INFO: ' + fyLabel + '\\n\\n' +
'COMPUTED METRICS (use these exact numbers):\\n' +
'- Total Reviews (active, non-deleted): ' + metrics.totalReviews + '\\n' +
'- Weekly Average Rating: ' + metrics.weeklyAvg + '\\n' +
'- PTD Average (' + periodLabel + '): ' + metrics.ptdAvg + ' (' + metrics.ptdCount + ' reviews)\\n' +
'- YTD Average (' + fyLabel + '): ' + metrics.ytdAvg + ' (' + metrics.ytdCount + ' reviews)\\n' +
'- Deleted this week: ' + metrics.deletedThisWeek + '\\n' +
'- Deleted ' + periodLabel + ' to date: ' + metrics.deletedPTD + '\\n' +
'- Deleted ' + fyLabel + ' to date: ' + metrics.deletedYTD + '\\n' +
'- Response Rate: 100%\\n' +
'- Response Time: < 1 day\\n\\n' +
'RATING DISTRIBUTION (non-deleted):\\n' +
Object.entries(metrics.ratingDist).map(([r,v]) => r + '★ – ' + v.count + ' (' + v.pct + '%%)').join('\\n') + '\\n\\n' +
'SOURCES (non-deleted):\\n' +
Object.entries(metrics.sources).map(([s,c]) => s + ' – ' + c).join('\\n') + '\\n\\n' +
(metrics.deletedThisWeek > 0 ? 'DELETED REVIEWS (' + metrics.deletedThisWeek + ' total, excluded from all ratings):\\n' + 
  metrics.deletedReviews.map(r => '- ' + formatAuthorName(r['Author']) + ' (' + r['Rating'] + '★ ' + r['Source'] + '): ' + (r['Review'] || '(no comment)')).join('\\n') + '\\n\\n' : '') +
'PROMOTER REVIEWS (4-5★):\\n' +
(promoters.length > 0 ? buildReviewList(promoters) : 'None this week') + '\\n\\n' +
'NEUTRAL REVIEWS (3★):\\n' +
(neutrals.length > 0 ? buildReviewList(neutrals) : 'None this week') + '\\n\\n' +
'DETRACTOR REVIEWS (1-2★):\\n' +
(detractors.length > 0 ? buildReviewList(detractors) : 'None this week') + '\\n\\n' +
'STAFF NAME DROPS (deterministic — already extracted from canonical roster, do NOT generate this section yourself):\\n' +
(metrics.nameDropsSection.length > 0
  ? metrics.nameDropsSection.map(d => '- ' + d.name + ': ' + d.period_total + ' period-to-date (+' + d.week_delta + ' this week)').join('\\n')
  : 'No staff mentioned by name this week') + '\\n\\n' +
'PRIOR PERIOD CONTEXT (' + (priorPeriodMetrics ? priorPeriodMetrics.periodLabel : 'P??') + ', use to anchor actionable insights and compare deltas):\\n' +
'- Prior period name drops: ' + (Object.keys(priorPeriodNameDrops).length > 0
  ? Object.entries(priorPeriodNameDrops).sort((a,b) => b[1]-a[1]).map(([n,c]) => n + '(' + c + ')').join(', ')
  : 'none') + '\\n' +
'- Prior period theme keyword counts: ' + (Object.keys(priorPeriodThemes).length > 0
  ? Object.entries(priorPeriodThemes).sort((a,b) => b[1]-a[1]).slice(0, 12).map(([k,v]) => k + '(' + v + ')').join(', ')
  : 'none') + '\\n' +
'- USE THIS to call out shifts: which staff are still showing up vs falling off, which themes are escalating or improving, what should the GM act on THIS WEEK that builds on last period\\u2019s patterns.\\n\\n' +
'COMPARISONS FROM HISTORY:\\n' +
(comparisonStr || 'No prior week data available (this may be the first week in the CSV)') + '\\n\\n' +
priorWeekReviewList + '\\n' +
'DAILY BREAKDOWN:\\n' +
Object.entries(metrics.dailyBreakdown).sort().map(([day, info]) => {
  const dayName = getDayName(info.date);
  return dayName + ' ' + day + ': ' + info.positive + ' positive, ' + info.neutral + ' neutral, ' + info.negative + ' negative';
}).join('\\n') + '\\n\\n' +
'---\\n\\n' +
historyContext + '\\n\\n---\\n\\n' +
'RETURN ONLY VALID JSON (no markdown, no code fences). Structure:\n{\n' +
'  "executive_summary": "1-2 sentence narrative summary with volume and rating trends",\n' +
'  "feedback_breakdown_narrative": "Full narrative paragraph. This week received X reviews (delta vs last week), average rating X.XX. Context about rating drivers. Response performance sentence.",\n' +
'  "review_observations": {\n' +
'    "promoters": ["bullet 1: theme + key detail from review text", "bullet 2", ...],\n' +
'    "neutrals": ["bullet text"] or ["None this week"],\n' +
'    "detractors": ["bullet 1: issue + specifics from review", ...]\n' +
'  },\n' +
'  "feedback_trends": {"positive": ["trend grounded in reviews", ...], "negative": ["trend grounded in reviews", ...]},\n' +
'  "keyword_trends": [\n' +
'    {"category": "Product / Drinks", "positive": "keyword (count), keyword (count)", "negative": "keyword (count) or \u2014"},\n' +
'    {"category": "Service", "positive": "...", "negative": "..."},\n' +
'    {"category": "Location / Atmosphere", "positive": "...", "negative": "..."},\n' +
'    {"category": "Value", "positive": "...", "negative": "..."},\n' +
'    {"category": "Customer Use Case", "positive": "...", "negative": "..."}\n' +
'  ],\n' +
'  "sentiment_by_day": [{"day": "Mon DD", "positive_text": "1-line positive themes", "negative_text": "negative notes or \u2014"}, ...],\n' +
'  "focus_points": {"keep_doing": ["actionable bullet tied to 5-star drivers", ...], "improve": ["actionable bullet tied to negative reviews", ...]}\n' +
'}\n\n' +
'RULES:\n' +
'- keyword_trends: exactly 5 categories. Text with counts like "food (3)" not numbers. Use dash if none.\n' +
'- sentiment_by_day: only days with reviews. Day format "Mon DD" (e.g. "Dec 8"). Text descriptions not counts.\n' +
'- review_observations: arrays of bullet strings (not objects). Each 1-2 sentences referencing review content.\n' +
'- feedback_breakdown_narrative: write the FULL narrative including volume/rating summary and response performance.\n' +
'- DO NOT include a name_drops field — staff name drops are extracted deterministically by the workflow, not the LLM.\n' +
'- Tone: concise, operational, upbeat but factual. Never invent facts not in reviews.';

const claudeRequestBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 4096,
  messages: [{ role: 'user', content: claudePrompt }]
});

// Ensure exactly 1 item returned with the prompt
if (!claudePrompt) {
  throw new Error('Failed to build Claude prompt. CSV text length: ' + csvText.length + ', Reviews: ' + allReviews.length);
}

return [{
  json: {
    claudePrompt,
    claudeRequestBody,
    metrics: {
      totalReviews: metrics.totalReviews,
      weeklyAvg: metrics.weeklyAvg,
      ptdAvg: metrics.ptdAvg,
      ptdCount: metrics.ptdCount,
      ytdAvg: metrics.ytdAvg,
      ytdCount: metrics.ytdCount,
      allTimeAvg: metrics.allTimeAvg,
      allTimeCount: metrics.allTimeCount,
      overallWeeklyAvgRating: metrics.overallWeeklyAvgRating,
      overallWeeklyAvgCount: metrics.overallWeeklyAvgCount,
      ytdLastWeekAvg: metrics.ytdLastWeekAvg,
      ptdLastWeekAvg: metrics.ptdLastWeekAvg,
      deletedThisWeek: metrics.deletedThisWeek,
      deletedPTD: metrics.deletedPTD,
      deletedYTD: metrics.deletedYTD,
      ratingDist: metrics.ratingDist,
      sources: metrics.sources,
      nameDropsSection: metrics.nameDropsSection,
      nameDropsThisWeek: metrics.nameDropsThisWeek,
      nameDropsThisPeriod: metrics.nameDropsThisPeriod
    },
    nameDropsSection: metrics.nameDropsSection,
    comparisons: {
      priorWeek: priorWeekMetrics,
      ptdHistory: ptdHistoryMetrics,
      priorPeriod: priorPeriodMetrics
    },
    weekInfo: {
      fyLabel,
      periodNum,
      periodLabel,
      weekNum,
      weekStart: formatDate(weekStart),
      weekEnd: formatDate(weekEnd),
      weekStartDisplay: wsDisplay,
      weekEndDisplay: weDisplay
    },
    fileName: 'HM ATX Feedback Report ' + fyLabel + ' ' + periodLabel + ' WK' + weekNum + '.docx',
    historyData: { weeks: [] },
    reportMemory: reportMemoryData,
    periodNameDropsUpdate,
    staleReports,
    mergedCsvText,
    comparisons: {
      priorWeek: priorWeekMetrics,
      ptdHistory: ptdHistoryMetrics,
      priorPeriod: priorPeriodMetrics
    }
  }
}];

const response = $json.content[0].text;
try {
  // Try to parse as JSON first
  const parsed = JSON.parse(response);
  return [{json: {report: JSON.stringify(parsed, null, 2), reportJson: parsed}}];
} catch(e) {
  // If it's not JSON, return raw text
  return [{json: {report: response, reportJson: null}}];
}

const reportJson = $json.reportJson;
const processData = $('Process CSV & Build Prompt').first().json;
const weekInfo = processData.weekInfo;
const metrics = processData.metrics;
const comparisons = processData.comparisons;
const fileName = processData.fileName;

if (!reportJson) {
  return [{ json: { error: 'No report JSON available', fileName } }];
}

const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, VerticalAlign,
  HeadingLevel, TableLayoutType } = require('docx');

// ---- STYLE CONSTANTS (matches ATX Feedback Report TEMPLATE.docx) ----
const LIME = 'C0FE4E';
const WHITE = 'FFFFFF';
const GRAY_BG = 'F2F2F2';
const BLACK = '000000';
const GRAY_BORDER = 'CCCCCC';

const noBorder = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const thinBorder = { style: BorderStyle.SINGLE, size: 1, color: GRAY_BORDER };
const thinBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

// 2-column grid (simplified from template's 4-col grid — visually identical)
const COL_LABEL = 1952;
const COL_CONTENT = 8985;
const TABLE_W = COL_LABEL + COL_CONTENT; // 10937

// ---- FONT HELPERS ----
function antonRun(text, ptSize, opts = {}) {
  return new TextRun({ text, font: 'Anton', size: ptSize * 2, bold: true, color: BLACK, ...opts });
}
function albertRun(text, ptSize, opts = {}) {
  return new TextRun({ text, font: 'Albert Sans', size: ptSize * 2, ...opts });
}

// ---- TABLE ROW HELPERS ----

// Green section header spanning full width
function sectionHeader(text) {
  return new TableRow({ children: [
    new TableCell({
      borders: noBorders, columnSpan: 2,
      width: { size: TABLE_W, type: WidthType.DXA },
      shading: { fill: LIME, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 120, right: 120 },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ children: [antonRun(text, 12)] })],
    }),
  ]});
}

// Label (lime) + Content (white) row
function contentRow(labelLines, contentChildren) {
  const labelParas = labelLines.length > 0
    ? labelLines.map((line, i) => new Paragraph({
        spacing: { after: 0 },
        children: [albertRun(line, i === 0 ? 10 : 9, { bold: true })],
      }))
    : [new Paragraph({ children: [albertRun('', 8)] })];

  return new TableRow({ children: [
    new TableCell({
      borders: noBorders,
      width: { size: COL_LABEL, type: WidthType.DXA },
      shading: { fill: LIME, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 80, right: 40 },
      verticalAlign: VerticalAlign.TOP,
      children: labelParas,
    }),
    new TableCell({
      borders: noBorders,
      width: { size: COL_CONTENT, type: WidthType.DXA },
      shading: { fill: WHITE, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 80 },
      verticalAlign: VerticalAlign.TOP,
      children: contentChildren,
    }),
  ]});
}

// Full-width content row (no label, white bg)
function fullWidthContent(contentChildren) {
  return new TableRow({ children: [
    new TableCell({
      borders: noBorders, columnSpan: 2,
      width: { size: TABLE_W, type: WidthType.DXA },
      shading: { fill: WHITE, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 80 },
      verticalAlign: VerticalAlign.TOP,
      children: contentChildren,
    }),
  ]});
}

// ---- NESTED TABLE HELPERS (auto-sizing) ----
function autoColumnWidths(headers, dataRows, totalWidth) {
  const minCol = 900;
  const numCols = headers.length;
  const maxLens = headers.map(h => String(h).length);
  dataRows.forEach(row => {
    row.forEach((cell, i) => {
      if (i < numCols) {
        const len = String(cell || '').length;
        if (len > maxLens[i]) maxLens[i] = len;
      }
    });
  });
  const weights = maxLens.map(l => Math.sqrt(Math.max(l, 1)));
  const totalWeight = weights.reduce((a, b) => a + b, 0);
  let widths = weights.map(w => Math.max(minCol, Math.floor((w / totalWeight) * totalWidth)));
  widths[widths.length - 1] += totalWidth - widths.reduce((a, b) => a + b, 0);
  return widths;
}

function buildAutoTable(headers, dataRows) {
  const totalW = COL_CONTENT;  // 8985 DXA
  const colWidths = autoColumnWidths(headers, dataRows, totalW);
  const rows = [];
  // Header row
  rows.push(new TableRow({
    children: headers.map((h, i) => new TableCell({
      borders: thinBorders,
      width: { size: colWidths[i], type: WidthType.DXA },
      shading: { fill: GRAY_BG, type: ShadingType.CLEAR },
      margins: { top: 60, bottom: 60, left: 100, right: 100 },
      children: [new Paragraph({ children: [albertRun(h, 9, { bold: true })] })],
    }))
  }));
  // Data rows
  dataRows.forEach(row => {
    rows.push(new TableRow({
      children: row.map((cell, i) => new TableCell({
        borders: thinBorders,
        width: { size: colWidths[i], type: WidthType.DXA },
        margins: { top: 50, bottom: 50, left: 100, right: 100 },
        verticalAlign: VerticalAlign.TOP,
        children: [new Paragraph({ children: [albertRun(String(cell || '\u2014'), 9)] })],
      }))
    }));
  });
  return new Table({
    width: { size: totalW, type: WidthType.DXA },
    columnWidths: colWidths,
    rows,
    layout: TableLayoutType.FIXED,
  });
}

