// ---- FEEDBACK BREAKDOWN ----
function buildFeedbackBreakdown() {
  const paras = [];
  const narrative = reportJson.feedback_breakdown_narrative || reportJson.executive_summary || '';

  // Narrative paragraph(s)
  if (narrative) {
    narrative.split('\n').filter(l => l.trim()).forEach(line => {
      paras.push(new Paragraph({
        spacing: { after: 120 },
        children: [albertRun(line.trim(), 11)],
      }));
    });
    paras.push(new Paragraph({ spacing: { after: 80 }, children: [] }));
  }

  // Computed metrics (always accurate, from data — not Claude)
  // Comparison helpers
  const comp = comparisons || {};
  const pw = comp.priorWeek;
  const pp = comp.priorPeriod;
  const ptdH = comp.ptdHistory;

  function reviewDelta(curr, prev) {
    if (prev === undefined || prev === null) return '';
    const d = curr - prev;
    if (d === 0) return ' (no change)';
    const arrow = d > 0 ? '\u2191' : '\u2193';
    return ' (' + arrow + ' ' + Math.abs(d) + ')';
  }
  function ratingDelta(curr, prev) {
    if (prev === undefined || prev === null) return '';
    const d = curr - prev;
    if (Math.abs(d) < 0.005) return ' (no change)';
    const arrow = d > 0 ? '\u2191' : '\u2193';
    // Show 2 decimals, but if very small show 3
    const formatted = Math.abs(d) < 0.01 ? Math.abs(d).toFixed(3) : Math.abs(d).toFixed(2);
    return ' (' + arrow + ' ' + formatted + ')';
  }

  const lines = [
    'Total Reviews: ' + metrics.totalReviews + reviewDelta(metrics.totalReviews, pw ? pw.totalReviews : null),
    'Weekly Average Rating: ' + metrics.weeklyAvg + ratingDelta(metrics.weeklyAvg, metrics.overallWeeklyAvgRating),
    'PTD Average (' + weekInfo.periodLabel + '): ' + metrics.ptdAvg + ratingDelta(metrics.ptdAvg, metrics.ptdLastWeekAvg),
    'YTD Average (' + weekInfo.fyLabel + '): ' + metrics.ytdAvg + ratingDelta(metrics.ytdAvg, metrics.ytdLastWeekAvg),
  ];

  if (metrics.deletedThisWeek > 0 || metrics.deletedPTD > 0) {
    lines.push('Deleted (excluded from rating calcs):');
    lines.push('  This week: ' + metrics.deletedThisWeek);
    lines.push('  ' + weekInfo.periodLabel + ' to date: ' + metrics.deletedPTD);
  }
  lines.push('Response Rate: 100%');
  lines.push('Response Time: < 1 day');

  lines.forEach(l => paras.push(new Paragraph({ spacing: { after: 20 }, children: [albertRun(l, 11)] })));

  // Week-over-Week Snapshot
  if (comp.priorWeek) {
    paras.push(new Paragraph({ spacing: { after: 60 }, children: [] }));
    paras.push(new Paragraph({ spacing: { after: 40 }, children: [albertRun('Week-over-Week Snapshot', 11, { bold: true })] }));

    const pwk = comp.priorWeek;
    const thisRate5 = metrics.totalReviews > 0 ? Math.round(((metrics.ratingDist[5] || {}).count || 0) / metrics.totalReviews * 100) : 0;
    const lastRate5 = pwk.totalReviews > 0 && pwk.ratingDist ? Math.round(((pwk.ratingDist[5] || {}).count || 0) / pwk.totalReviews * 100) : null;
    const thisDetractors = ((metrics.ratingDist[1] || {}).count || 0) + ((metrics.ratingDist[2] || {}).count || 0);
    const lastDetractors = pwk.ratingDist ? ((pwk.ratingDist[1] || {}).count || 0) + ((pwk.ratingDist[2] || {}).count || 0) : null;

    const wowLines = [
      'Reviews: ' + (pwk.totalReviews || 0) + ' \u2192 ' + metrics.totalReviews + reviewDelta(metrics.totalReviews, pwk.totalReviews),
      'Average Rating: ' + (pwk.weeklyAvg || 0) + ' \u2192 ' + metrics.weeklyAvg + ' (overall avg: ' + (metrics.overallWeeklyAvgRating || 'N/A') + ')',
    ];
    if (lastRate5 !== null) {
      const r5d = thisRate5 - lastRate5;
      const r5arrow = r5d > 0 ? '\u2191' : r5d < 0 ? '\u2193' : '';
      wowLines.push('5\u2605 Rate: ' + lastRate5 + '% \u2192 ' + thisRate5 + '%' + (r5d !== 0 ? ' (' + r5arrow + ' ' + Math.abs(r5d) + '%)' : ''));
    }
    if (lastDetractors !== null) {
      const dd = thisDetractors - lastDetractors;
      const darrow = dd > 0 ? '\u2191' : dd < 0 ? '\u2193' : '';
      wowLines.push('Detractors (1-2\u2605): ' + lastDetractors + ' \u2192 ' + thisDetractors + (dd !== 0 ? ' (' + darrow + ' ' + Math.abs(dd) + ')' : ''));
    }

    wowLines.forEach(l => paras.push(new Paragraph({ spacing: { after: 10 }, children: [albertRun(l, 11)] })));
  }

  // Trend Context
  if (metrics.allTimeAvg || comp.priorWeek) {
    paras.push(new Paragraph({ spacing: { after: 60 }, children: [] }));
    paras.push(new Paragraph({ spacing: { after: 40 }, children: [albertRun('Trend Context', 11, { bold: true })] }));

    const trendLines = [];
    if (metrics.allTimeAvg && metrics.weeklyAvg) {
      const diff = Math.round((metrics.weeklyAvg - metrics.allTimeAvg) * 100) / 100;
      if (diff > 0) {
        trendLines.push('This week\u2019s average (' + metrics.weeklyAvg + ') is above the ' + weekInfo.fyLabel + ' weekly average of ' + metrics.allTimeAvg);
      } else if (diff < 0) {
        trendLines.push('This week\u2019s average (' + metrics.weeklyAvg + ') is below the ' + weekInfo.fyLabel + ' weekly average of ' + metrics.allTimeAvg);
      } else {
        trendLines.push('This week\u2019s average (' + metrics.weeklyAvg + ') matches the ' + weekInfo.fyLabel + ' weekly average');
      }
    }
    if (comp.priorPeriod) {
      const ppAvg = comp.priorPeriod.weeklyAvg;
      const ptdDiff = Math.round((metrics.ptdAvg - ppAvg) * 100) / 100;
      const ptdArrow = ptdDiff > 0 ? '\u2191' : ptdDiff < 0 ? '\u2193' : '';
      trendLines.push(weekInfo.periodLabel + ' to date (' + metrics.ptdAvg + ') vs ' + comp.priorPeriod.periodLabel + ' (' + ppAvg + '): ' + (ptdDiff !== 0 ? ptdArrow + ' ' + Math.abs(ptdDiff).toFixed(2) : 'no change'));
    }

    trendLines.forEach(l => paras.push(new Paragraph({ spacing: { after: 10 }, children: [albertRun(l, 11)] })));
  }

  // Rating Distribution
  paras.push(new Paragraph({ spacing: { after: 60 }, children: [] }));
  paras.push(new Paragraph({ spacing: { after: 20 }, children: [albertRun('Rating Distribution', 11, { bold: true })] }));
  const dist = metrics.ratingDist || {};
  [5, 4, 3, 2, 1].forEach(s => {
    const d = dist[s];
    if (d && d.count > 0) {
      paras.push(new Paragraph({ spacing: { after: 10 }, children: [albertRun(s + '\u2605 \u2013 ' + d.count + ' (' + d.pct + '%)', 11)] }));
    }
  });

  // Sources
  paras.push(new Paragraph({ spacing: { after: 60 }, children: [] }));
  paras.push(new Paragraph({ spacing: { after: 20 }, children: [albertRun('Sources', 11, { bold: true })] }));
  Object.entries(metrics.sources || {}).forEach(([src, cnt]) => {
    paras.push(new Paragraph({ spacing: { after: 10 }, children: [albertRun(src + ' \u2013 ' + cnt, 11)] }));
  });

  return paras;
}

// ---- OBSERVATION BULLETS ----
function buildBullets(items) {
  if (!items || (Array.isArray(items) && items.length === 0)) {
    return [new Paragraph({ children: [albertRun('None this week', 11)] })];
  }
  if (typeof items === 'string') {
    return [new Paragraph({ children: [albertRun(items, 11)] })];
  }
  if (Array.isArray(items)) {
    return items.map(item => {
      const text = typeof item === 'string' ? item : (item.summary || item.snippet || JSON.stringify(item));
      return new Paragraph({ spacing: { after: 80 }, children: [albertRun('  ' + text, 11)] });
    });
  }
  // Legacy {summary, snippets} format
  if (items.summary) {
    return [new Paragraph({ spacing: { after: 80 }, children: [albertRun(items.summary, 11)] })];
  }
  return [new Paragraph({ children: [albertRun('None this week', 11)] })];
}

// ---- FEEDBACK TRENDS ----
function buildTrends() {
  const t = reportJson.feedback_trends || {};
  const paras = [];
  paras.push(new Paragraph({ spacing: { after: 60 }, children: [albertRun('\u2705 Positive Trends', 11, { bold: true })] }));
  (t.positive || []).forEach(b => paras.push(new Paragraph({ spacing: { after: 60 }, children: [albertRun(b, 11)] })));
  paras.push(new Paragraph({ spacing: { after: 100 }, children: [] }));
  paras.push(new Paragraph({ spacing: { after: 60 }, children: [albertRun('\u274C Negative Trends', 11, { bold: true })] }));
  (t.negative || []).forEach(b => paras.push(new Paragraph({ spacing: { after: 60 }, children: [albertRun(b, 11)] })));
  return paras;
}

// ---- KEYWORD TRENDS TABLE ----
function buildKeywordTable() {
  const kw = reportJson.keyword_trends || [];
  const categories = ['Product / Drinks', 'Service', 'Location / Atmosphere', 'Value', 'Customer Use Case'];
  const headers = ['Category', 'Top Positive Mentions', 'Top Negative Mentions'];
  const dataRows = categories.map(cat => {
    const item = kw.find(k => k.category && k.category.toLowerCase().includes(cat.split(' / ')[0].toLowerCase())) || {};
    const pos = item.positive || item.positive_mentions || '\u2014';
    const neg = item.negative || item.negative_mentions || '\u2014';
    return [cat, typeof pos === 'number' ? String(pos) : pos, typeof neg === 'number' ? String(neg) : neg];
  });
  return buildAutoTable(headers, dataRows);
}

// ---- SENTIMENT BY DAY TABLE ----
function buildSentimentTable() {
  const days = reportJson.sentiment_by_day || [];
  const headers = ['Day', 'Positive Sentiment', 'Negative / Improvement Notes'];
  const dataRows = days.map(d => {
    const pos = d.positive_text || d.positive || '\u2014';
    const neg = d.negative_text || d.negative || '\u2014';
    return [d.day || '', typeof pos === 'number' ? String(pos) : pos, typeof neg === 'number' ? String(neg) : neg];
  });
  return buildAutoTable(headers, dataRows);
}

